<div class="flex items-center justify-between mb-4"><div><h1 class="text-2xl font-bold text-white">Users</h1><p class="text-slate-400 mt-1"><?php echo count($rows); ?> registered users</p></div><button class="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm rounded-lg transition-colors">Add User</button></div>
<div class="bg-[#13151f] border border-[#2a2d3e] rounded-xl overflow-hidden"><div class="grid grid-cols-6 px-5 py-3 text-xs uppercase tracking-wide text-slate-500 border-b border-[#2a2d3e]"><div>Email</div><div>Name</div><div>Role</div><div>Status</div><div>Created</div><div></div></div><?php foreach ($rows as $row): ?><div class="grid grid-cols-6 px-5 py-3 text-sm border-b border-[#1e2130] last:border-0"><div class="font-medium text-white"><?php echo html_escape($row['email']); ?></div><div class="text-slate-300"><?php echo html_escape($row['name']); ?></div><div class="text-xs text-slate-400 capitalize"><?php echo html_escape($row['role']); ?></div><div><span class="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium border bg-green-500/15 text-green-400 border-green-500/30"><?php echo html_escape($row['status']); ?></span></div><div class="text-slate-400"><?php echo html_escape(substr($row['created_at'], 0, 10)); ?></div><div class="text-right"><button class="text-red-400 hover:text-red-300 text-xs">Delete</button></div></div><?php endforeach; ?></div>
